#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
if [ ! -f .env.web ]; then
  echo 'Вначале выполни: python3 scripts/create_web_env.py' >&2
  exit 1
fi
set -a
# credentials generated by create_web_env.py; no whitespace or shell syntax
source .env.web
set +a
docker compose exec -T db psql -X -v ON_ERROR_STOP=1 -U postgres -d postgres -v "authpw=$WEB_AUTH_PASSWORD" <<'SQL'
SELECT format('CREATE ROLE registry_web_auth LOGIN PASSWORD %L', :'authpw')
 WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='registry_web_auth') \gexec
SELECT format('ALTER ROLE registry_web_auth WITH PASSWORD %L', :'authpw') \gexec
SELECT 'CREATE DATABASE registry_auth OWNER registry_web_auth'
 WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname='registry_auth') \gexec
REVOKE ALL ON DATABASE registry_auth FROM PUBLIC;
GRANT CONNECT ON DATABASE registry_auth TO registry_web_auth;
SQL
echo 'Отдельная БД registry_auth подготовлена. military_lab не изменена.'
